local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "SELENE"
Junkie.identifier = "1089162"
Junkie.provider = "SELENE W"

local result = (function()
    getgenv().UI_CLOSED = false

    local Players = game:GetService("Players")

    local function saveKey(key)
        pcall(function() writefile("verified_key.txt", key) end)
    end
    local function loadKey()
        local ok, v = pcall(readfile, "verified_key.txt")
        return ok and v or nil
    end
    local function clearKey()
        pcall(delfile, "verified_key.txt")
    end

    -- Silent revalidation — no GUI if already valid
    local savedKey = loadKey() or getgenv().SCRIPT_KEY
    if savedKey then
        local r = Junkie.check_key(savedKey)
        if r and r.valid then
            getgenv().SCRIPT_KEY = (r.message == "KEYLESS") and "KEYLESS" or savedKey
            return getgenv().SCRIPT_KEY
        else
            clearKey()
        end
    else
        local r = Junkie.check_key(nil)
        if r and r.valid and r.message == "KEYLESS" then
            getgenv().SCRIPT_KEY = "KEYLESS"
            return getgenv().SCRIPT_KEY
        end
    end

    -- Colors
    local C = {
        bg        = Color3.fromRGB(14, 16, 21),
        panel     = Color3.fromRGB(22, 25, 33),
        titleBar  = Color3.fromRGB(18, 20, 27),
        border    = Color3.fromRGB(45, 50, 65),
        inputBg   = Color3.fromRGB(28, 32, 43),
        btnBlue   = Color3.fromRGB(56, 120, 230),
        btnGreen  = Color3.fromRGB(34, 160, 90),
        textMain  = Color3.fromRGB(225, 230, 240),
        textMuted = Color3.fromRGB(110, 118, 135),
        success   = Color3.fromRGB(60, 210, 120),
        error     = Color3.fromRGB(230, 75, 75),
        accent    = Color3.fromRGB(80, 140, 255),
    }

    local function addCorner(parent, radius)
        local c = Instance.new("UICorner", parent)
        c.CornerRadius = UDim.new(0, radius or 8)
        return c
    end
    local function addStroke(parent, color, thickness)
        local s = Instance.new("UIStroke", parent)
        s.Color = color or C.border
        s.Thickness = thickness or 1
        return s
    end

    -- ScreenGui
    local Gui = Instance.new("ScreenGui")
    Gui.Name = "KeySystemUI"
    Gui.ResetOnSpawn = false
    Gui.IgnoreGuiInset = true
    Gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    Gui.Parent = game:GetService("CoreGui")

    -- Backdrop
    local Backdrop = Instance.new("Frame", Gui)
    Backdrop.Size = UDim2.new(1, 0, 1, 0)
    Backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    Backdrop.BackgroundTransparency = 0.55
    Backdrop.BorderSizePixel = 0

    -- Main window
    local Win = Instance.new("Frame", Gui)
    Win.Size = UDim2.new(0, 360, 0, 185)
    Win.Position = UDim2.new(0.5, -180, 0.5, -92)
    Win.BackgroundColor3 = C.panel
    Win.BorderSizePixel = 0
    addCorner(Win, 12)
    addStroke(Win, C.border, 1)

    -- Accent line at top of window
    local AccentLine = Instance.new("Frame", Win)
    AccentLine.Size = UDim2.new(1, -24, 0, 2)
    AccentLine.Position = UDim2.new(0, 12, 0, 0)
    AccentLine.BackgroundColor3 = C.btnBlue
    AccentLine.BorderSizePixel = 0
    addCorner(AccentLine, 2)
    local accentGrad = Instance.new("UIGradient", AccentLine)
    accentGrad.Color = ColorSequence.new{
        ColorSequenceKeypoint.new(0, C.btnBlue),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(140, 80, 240))
    }

    -- Title bar
    local TitleBar = Instance.new("Frame", Win)
    TitleBar.Size = UDim2.new(1, 0, 0, 42)
    TitleBar.Position = UDim2.new(0, 0, 0, 2)
    TitleBar.BackgroundColor3 = C.titleBar
    TitleBar.BorderSizePixel = 0

    -- fix bottom corners
    local TitleFix = Instance.new("Frame", TitleBar)
    TitleFix.Size = UDim2.new(1, 0, 0, 10)
    TitleFix.Position = UDim2.new(0, 0, 1, -10)
    TitleFix.BackgroundColor3 = C.titleBar
    TitleFix.BorderSizePixel = 0

    -- dot decorations
    for i, col in ipairs({
        Color3.fromRGB(255, 95, 87),
        Color3.fromRGB(255, 189, 46),
        Color3.fromRGB(40, 200, 100)
    }) do
        local dot = Instance.new("Frame", TitleBar)
        dot.Size = UDim2.new(0, 10, 0, 10)
        dot.Position = UDim2.new(0, 10 + (i - 1) * 16, 0.5, -5)
        dot.BackgroundColor3 = col
        dot.BorderSizePixel = 0
        addCorner(dot, 99)
    end

    local TitleLabel = Instance.new("TextLabel", TitleBar)
    TitleLabel.Size = UDim2.new(1, 0, 1, 0)
    TitleLabel.BackgroundTransparency = 1
    TitleLabel.Text = "🔑  Key Verification"
    TitleLabel.TextColor3 = C.textMain
    TitleLabel.TextSize = 13
    TitleLabel.Font = Enum.Font.GothamSemibold
    TitleLabel.TextXAlignment = Enum.TextXAlignment.Center

    -- Subtitle
    local SubLabel = Instance.new("TextLabel", Win)
    SubLabel.Size = UDim2.new(1, -24, 0, 16)
    SubLabel.Position = UDim2.new(0, 12, 0, 50)
    SubLabel.BackgroundTransparency = 1
    SubLabel.Text = "Enter your key or get one below to continue."
    SubLabel.TextColor3 = C.textMuted
    SubLabel.TextSize = 11
    SubLabel.Font = Enum.Font.Gotham
    SubLabel.TextXAlignment = Enum.TextXAlignment.Left

    -- Input
    local InputFrame = Instance.new("Frame", Win)
    InputFrame.Size = UDim2.new(1, -24, 0, 36)
    InputFrame.Position = UDim2.new(0, 12, 0, 74)
    InputFrame.BackgroundColor3 = C.inputBg
    InputFrame.BorderSizePixel = 0
    addCorner(InputFrame, 8)
    local inputStroke = addStroke(InputFrame, C.border, 1)

    local InputBox = Instance.new("TextBox", InputFrame)
    InputBox.Size = UDim2.new(1, -12, 1, 0)
    InputBox.Position = UDim2.new(0, 6, 0, 0)
    InputBox.BackgroundTransparency = 1
    InputBox.PlaceholderText = "Paste your key here..."
    InputBox.PlaceholderColor3 = Color3.fromRGB(80, 88, 105)
    InputBox.Text = ""
    InputBox.TextColor3 = C.textMain
    InputBox.TextSize = 13
    InputBox.Font = Enum.Font.Gotham
    InputBox.ClearTextOnFocus = false

    InputBox.Focused:Connect(function()
        inputStroke.Color = C.accent
        inputStroke.Thickness = 1.5
    end)
    InputBox.FocusLost:Connect(function(enter)
        inputStroke.Color = C.border
        inputStroke.Thickness = 1
        if enter then
            -- fire verify below
        end
    end)

    -- Buttons row
    local BtnGet = Instance.new("TextButton", Win)
    BtnGet.Size = UDim2.new(0.5, -18, 0, 34)
    BtnGet.Position = UDim2.new(0, 12, 0, 120)
    BtnGet.BackgroundColor3 = C.btnBlue
    BtnGet.BorderSizePixel = 0
    BtnGet.Text = "Get Key"
    BtnGet.TextColor3 = Color3.fromRGB(255, 255, 255)
    BtnGet.TextSize = 13
    BtnGet.Font = Enum.Font.GothamSemibold
    BtnGet.AutoButtonColor = false
    addCorner(BtnGet, 8)

    local BtnVerify = Instance.new("TextButton", Win)
    BtnVerify.Size = UDim2.new(0.5, -18, 0, 34)
    BtnVerify.Position = UDim2.new(0.5, 6, 0, 120)
    BtnVerify.BackgroundColor3 = C.btnGreen
    BtnVerify.BorderSizePixel = 0
    BtnVerify.Text = "Verify Key"
    BtnVerify.TextColor3 = Color3.fromRGB(255, 255, 255)
    BtnVerify.TextSize = 13
    BtnVerify.Font = Enum.Font.GothamSemibold
    BtnVerify.AutoButtonColor = false
    addCorner(BtnVerify, 8)

    -- Hover tints
    local function hoverBtn(btn, base, hover)
        btn.MouseEnter:Connect(function()
            btn.BackgroundColor3 = hover
        end)
        btn.MouseLeave:Connect(function()
            btn.BackgroundColor3 = base
        end)
        btn.MouseButton1Down:Connect(function()
            btn.BackgroundColor3 = base
        end)
        btn.MouseButton1Up:Connect(function()
            btn.BackgroundColor3 = hover
        end)
    end
    hoverBtn(BtnGet,    C.btnBlue,  Color3.fromRGB(76, 140, 255))
    hoverBtn(BtnVerify, C.btnGreen, Color3.fromRGB(44, 185, 110))

    -- Status
    local Status = Instance.new("TextLabel", Win)
    Status.Size = UDim2.new(1, -24, 0, 14)
    Status.Position = UDim2.new(0, 12, 1, -20)
    Status.BackgroundTransparency = 1
    Status.Text = ""
    Status.TextColor3 = C.textMuted
    Status.TextSize = 11
    Status.Font = Enum.Font.Gotham
    Status.TextXAlignment = Enum.TextXAlignment.Left

    local function setStatus(msg, color)
        Status.Text = msg
        Status.TextColor3 = color or C.textMuted
    end

    local function closeGui()
        getgenv().UI_CLOSED = true
        Gui:Destroy()
    end

    -- Get Key
    BtnGet.MouseButton1Click:Connect(function()
        local link = Junkie.get_key_link()
        if link then
            if setclipboard then
                setclipboard(link)
                setStatus("✓  Link copied! Paste it in your browser.", C.success)
            else
                setStatus(link, C.accent)
            end
        else
            setStatus("✗  Could not retrieve link.", C.error)
        end
    end)

    -- Verify Key
    local function doVerify()
        local key = InputBox.Text:gsub("%s+", "")
        if key == "" then
            setStatus("✗  Please enter a key first.", C.error)
            return
        end

        BtnVerify.Active = false
        BtnVerify.Text = "Checking..."
        setStatus("Verifying key...", C.accent)

        local r = Junkie.check_key(key)
        if r and r.valid then
            saveKey(key)
            getgenv().SCRIPT_KEY = key
            setStatus("✓  Key verified! Loading...", C.success)
            BtnVerify.Text = "Verified ✓"
            task.wait(0.7)
            closeGui()
        else
            setStatus("✗  Invalid or expired key.", C.error)
            BtnVerify.Text = "Verify Key"
            BtnVerify.Active = true
        end
    end

    BtnVerify.MouseButton1Click:Connect(doVerify)
    InputBox.FocusLost:Connect(function(enter)
        if enter then doVerify() end
    end)

    while not getgenv().UI_CLOSED do task.wait(0.1) end
    return getgenv().SCRIPT_KEY
end)()

